  ports={runtime:{async block(){return{timestamp:'1000'};}},system,account:{descriptor:()=>copy(descriptor)}};let service=Object.freeze(Object.create(null));services.set(service,ports);await providerModule.bindOriginalPagedNativeProviderV3(provider,service);const sealed=await providerModule.sealOriginalPagedNativeProviderRetentionV3(provider,token(provider,'SEAL',journalPassword)),credential=await readPagedNativeProviderCredentialV3(directory,journalPassword,{profile:PAGED_NATIVE_PROVIDER_RETENTION_PROFILE_V3,providerIdentity:sealed.providerIdentity,configurationSHA256:sealed.configurationSHA256}),vault=new Vault(join(directory,'provider.vault')),scope={descriptor,graphId:'graph-executor-host-v5',rootId:h('executor-root'),revision:2,budget:'100',settleBefore:'2000',sourceScope:system.scope,assetIdentity:system.assetIdentity},permit=Object.freeze(Object.create(null));issued.set(permit,{kind:'quote',provider,scope});
  const input={preparationId:'paged-page-'+h('executor-preparation').slice(0,32),pageIndex:'0',operationId:h('executor-operation'),nodes:[{id:'ethereum',ordinal:'0',amount:'100'}],collectBy:descriptor.deadlineMs,maximumFeeAtomic:'1000'},before={nativeSigns,nativeSends},prepared=await providerModule.prepareOriginalPagedNativeExecutorPayoutsV5(provider,input,permit),certificate=XP.normalizeDevicePagedExecutorPayoutCustodyV5(prepared.certificates[0]),terms=certificate.terms,pub=key=>createPublicKey({format:'jwk',key:{kty:'EC',crv:'secp256k1',x:Buffer.from(key.slice(2,66),'hex').toString('base64url'),y:Buffer.from(key.slice(66),'hex').toString('base64url')}}),frame=XP.devicePagedExecutorPayoutCustodyFrameV5(certificate.termsSHA256);
  assert.equal(verify('sha256',frame,{key:pub(terms.providerPublicKey),dsaEncoding:'ieee-p1363'},Buffer.from(certificate.signature,'hex')),true);assert.equal(verify('sha256',frame,{key:pub('04'+terms.opening.x+terms.opening.y),dsaEncoding:'ieee-p1363'},Buffer.from(certificate.ownershipSignature,'hex')),true);assert.notEqual('04'+terms.opening.x+terms.opening.y,terms.providerPublicKey);assert.equal(walletNoteCommitment(descriptor.scope,descriptor.policy,terms.opening).toString('hex'),terms.commitment);assert.ok(!JSON.stringify(prepared).includes('pkcs8'));assert.ok(!(await readFile(vault.path,'utf8')).includes(terms.opening.secret));assert.deepEqual(await providerModule.prepareOriginalPagedNativeExecutorPayoutsV5(provider,input,permit),prepared);await assert.rejects(providerModule.prepareOriginalPagedNativeExecutorPayoutsV5({...provider},input,permit));await assert.rejects(providerModule.prepareOriginalPagedNativeExecutorPayoutsV5(provider,{...input,operationId:h('foreign')},permit),/PREPARATION_REUSE|strictly equal/);
