  issued.get(permit).invoiceRequests=[{id:'ethereum',ordinal:'0',nodeDigest:h('executor-node'),payoutCommitment:terms.commitment,x:terms.opening.x,y:terms.opening.y}];const invoices=await providerModule.signOriginalPagedNativeExecutorPayoutInvoicesV5(provider,{profile:'DEVICE_PAGED_EXECUTOR_PAYOUT_INVOICES_V5',pageIndex:'0',ids:['ethereum']},permit);assert.equal(invoices.invoices.length,1);assert.deepEqual(invoices,await providerModule.signOriginalPagedNativeExecutorPayoutInvoicesV5(provider,{profile:'DEVICE_PAGED_EXECUTOR_PAYOUT_INVOICES_V5',pageIndex:'0',ids:['ethereum']},permit));
  function payoutToken(changed={}){const cap=Object.freeze(Object.create(null)),request={account:ports.account,runtime:ports.runtime,system,descriptor,graphId:scope.graphId,rootId:scope.rootId,revision:scope.revision,authorizationRoot:h('executor-auth'),planSHA256:h('executor-plan'),jobId:'executor-host-payout-job',epoch:'1',expiresAt:terms.collectBy,payout:{id:'ethereum',ordinal:'0',commitment:terms.commitment,nullifier:terms.nullifier,amountAtomic:'100',beneficiary:terms.beneficiary,certificateSHA256:certificate.termsSHA256},...changed};issued.set(cap,{kind:'payout',provider,request,used:false});return cap;}
